import {hospitals} from './seed.js';
import {sampleStaff} from './sample-staff.js';
const sampleAssignment=s=>sampleStaff.find(x=>x.email===s.email);
const fixedSample=s=>!!sampleAssignment(s);
const assignedRole=s=>sampleAssignment(s)?.role||s.role||s.requestedRole;
const assignedFacility=s=>sampleAssignment(s)?.facilityId||s.facilityId||s.requestedFacility;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let actor;
async function api(path,input){const r=await fetch(path,{method:input?'POST':'GET',headers:input?{'Content-Type':'application/json'}:{},body:input?JSON.stringify(input):undefined});const data=await r.json();if(r.status===401){location.assign('/login.html');throw Error('Sign in again.');}if(!r.ok)throw Error(data.error||'Could not save this change.');return data;}
async function load(){const me=await api('/api/auth/me');actor=me.actor;if(actor.role!=='admin'){location.assign('/');return;}const staff=await api('/api/staff'),policy=await api('/api/policy'),data=await api('/api/requests');
 $('#staff-app').innerHTML=`<header class="core-header"><a class="core-brand" href="/staff.html"><img class="brand-logo" data-testid="brand-logo" src="/logo.svg" alt="Hospital Connect logo"><span>Hospital Connect<small>Sample administrator</small></span></a><nav class="core-nav"><a href="/network.html">BC map</a><a href="/about.html">About Us</a><a href="/data-care.html">Data care</a><button id="sign-out" data-testid="sign-out">Sign out</button></nav></header><div class="core-banner">Shared example accounts only. Verification here is a prototype exercise using invented employee numbers, not proof of actual employment. Real patient data stays blocked.</div><h1>Staff access and data care</h1><p id="staff-error" class="core-error" role="alert"></p><p id="staff-status" class="core-alert" role="status"></p><div class="access-grid"><section class="panel"><h2>Review sample access requests</h2><div data-testid="staff-list">${staff.staff.map(s=>`<article class="staff-card" data-testid="staff-${s.employeeNumber}"><strong>${esc(s.name)}</strong><p>${esc(s.email)} · ${esc(s.employeeNumber)}<br>Status: ${esc(s.status)} · ${esc(s.role||s.requestedRole||'unassigned')}</p>${s.userId!==actor.userId?`<label class="field"><span>Assigned role${fixedSample(s)?' · fixed sample desk':''}</span><select data-role="${s.userId}" ${fixedSample(s)?'disabled':''}><option value="hospital" ${assignedRole(s)==='hospital'?'selected':''}>Hospital reviewer</option><option value="ems" ${assignedRole(s)==='ems'?'selected':''}>EMS coordinator</option></select></label><label class="field"><span>Assigned facility</span><select data-facility="${s.userId}" ${fixedSample(s)?'disabled':''}>${hospitals.map(h=>`<option value="${h.id}" ${h.id===assignedFacility(s)?'selected':''}>${esc(h.name)}</option>`).join('')}</select></label><label class="field"><span>Verification decision / reason</span><input data-reason="${s.userId}" placeholder="Example employee number checked"></label><label class="check"><input type="checkbox" data-verified="${s.userId}"> I checked this invented number against the sample staff list.</label><div class="buttonrow"><button class="primary" data-staff-action="approved" data-user="${s.userId}">Approve</button><button class="secondary" data-staff-action="rejected" data-user="${s.userId}">Reject</button><button class="secondary" data-staff-action="suspended" data-user="${s.userId}">Suspend</button></div>`:'<small>Current administrator account</small>'}</article>`).join('')}</div></section><div><section class="panel"><h2>Example review and backup settings</h2><form id="policy-form"><label class="field"><span>Sample response target (minutes)</span><input id="response-minutes" data-testid="response-minutes" type="number" min="1" max="1440" value="${policy.responseMinutes}" required></label><label class="field"><span>Sample backup contact</span><input id="backup-contact" data-testid="backup-contact" value="${esc(policy.backupContact)}" maxlength="200" required></label><p class="muted">Start the backup contact with DEMO. These targets do not set a clinically safe waiting time or promise 24/7 staffing.</p><button class="primary" data-testid="save-policy">Save sample policy</button></form></section><section class="panel"><h2>Storage and deletion</h2><p>${esc(policy.retention)}</p><p>Deleting a request removes it from the active app store and leaves its reference, acting staff and reason in the audit history. Provider backup retention needs separate review before real-patient use.</p><div data-testid="deletion-list">${data.requests.map(r=>`<form class="delete-form staff-card" data-record="${r.recordId}"><strong>${esc(r.id)} · ${esc(r.resource)}</strong><label class="field"><span>Type ${esc(r.id)} to confirm</span><input name="reference" required></label><label class="field"><span>Deletion reason</span><input name="reason" required></label><button class="secondary">Delete example request</button></form>`).join('')||'<p>No example requests to delete.</p>'}</div></section></div></div><section class="panel"><h2>Administrative history</h2><ol data-testid="admin-audit">${staff.audit.sort((a,b)=>b.at-a.at).map(e=>`<li>${esc(e.name)} · ${esc(e.action)} · ${esc(e.reference)} · ${esc(new Date(e.at).toLocaleString())}${e.reason?' · '+esc(e.reason):''}</li>`).join('')||'<li>No administrative actions yet.</li>'}</ol></section>`;
 $('#sign-out').onclick=async()=>{await api('/api/auth/logout',{});location.assign('/login.html');};
 document.querySelectorAll('[data-staff-action]').forEach(b=>b.onclick=()=>run(async()=>{const id=b.dataset.user;await api('/api/staff/'+id,{status:b.dataset.staffAction,role:$(`[data-role="${id}"]`).value,facilityId:$(`[data-facility="${id}"]`).value,employeeVerified:$(`[data-verified="${id}"]`).checked,reason:$(`[data-reason="${id}"]`).value});await load();$('#staff-status').textContent='Staff decision recorded.';}));
 $('#policy-form').onsubmit=e=>{e.preventDefault();run(async()=>{await api('/api/policy',{responseMinutes:Number($('#response-minutes').value),backupContact:$('#backup-contact').value});$('#staff-status').textContent='Sample policy saved.';});};
 document.querySelectorAll('.delete-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();const values=new FormData(f);run(async()=>{await api('/api/requests/'+f.dataset.record+'/delete',{reference:values.get('reference'),reason:values.get('reason')});await load();$('#staff-status').textContent='Example request deleted; audit metadata retained.';});});
}
let busy=false;async function run(fn){if(busy)return;busy=true;$('#staff-error').textContent='';try{await fn();}catch(e){$('#staff-error').textContent=e.message;}finally{busy=false;}}
load().catch(e=>{$('#staff-app').innerHTML='<h1>Staff administration unavailable</h1><p role="alert">'+esc(e.message)+'</p><a href="/login.html">Return to sign-in</a>';});
